{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Execution Desk Data",
    "operation": "add",
    "widgets_json": {
      "venue_scorecard": {
        "name": "Venue Scorecard",
        "description": "Execution quality by venue.",
        "endpoint": "/venue-scorecard",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "venue",
            "type": "text",
            "label": "Venue",
            "value": "ARCA",
            "description": "Venue in focus."
          }
        ],
        "data": {
          "columnsDefs": [
            {
              "field": "fills",
              "headerName": "Fills",
              "cellDataType": "number"
            },
            {
              "field": "slippage_pct",
              "headerName": "Slippage %",
              "cellDataType": "number",
              "formatterFn": "percent"
            },
            {
              "field": "venue",
              "headerName": "Venue",
              "cellDataType": "text"
            }
          ]
        },
        "staleTime": 900000
      },
      "exception_metric": {
        "name": "Exceptions",
        "description": "Open execution exceptions.",
        "endpoint": "/exception-count",
        "type": "metric",
        "w": 5,
        "h": 4
      },
      "slippage_chart": {
        "name": "Slippage by Venue",
        "description": "Plotly slippage distribution by venue.",
        "endpoint": "/slippage-by-venue",
        "type": "chart",
        "w": 20,
        "h": 9,
        "raw": true
      }
    }
  }
}

